package com.rastudio.commerce.auth;
import com.rastudio.commerce.security.TenantPrincipal; import jakarta.validation.Valid; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService auth; private final boolean exposeVerificationToken; public AuthController(AuthService auth,@Value("${app.expose-verification-token}") boolean exposeVerificationToken){this.auth=auth;this.exposeVerificationToken=exposeVerificationToken;} @PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@Valid @RequestBody AuthService.RegisterRequest r){var result=auth.register(r);var body=new LinkedHashMap<String,Object>();body.put("success",true);body.put("message","Registration created. Verify the email address before signing in.");body.put("user",result.user());if(exposeVerificationToken)body.put("verificationToken",result.verificationToken());return body;} @PostMapping("/verify-email") public Map<String,Object> verify(@RequestBody Map<String,String> r){return Map.of("success",true,"user",auth.verify(r.get("token")));} @PostMapping("/login") public AuthService.AuthResponse login(@Valid @RequestBody AuthService.LoginRequest r){return auth.login(r);} @PostMapping("/refresh") public AuthService.AuthResponse refresh(@RequestBody Map<String,String> r){return auth.refresh(r.get("refreshToken"));} @PostMapping("/logout") @ResponseStatus(HttpStatus.NO_CONTENT) public void logout(@AuthenticationPrincipal TenantPrincipal p,@RequestBody Map<String,String> r){auth.logout(p.userId(),r.get("refreshToken"));} @GetMapping("/me") public AuthService.UserResponse me(@AuthenticationPrincipal TenantPrincipal p){return auth.me(p.userId());} }
